import { defaultParams } from "../catalog/params";
import { DESK_TYPE, type Catalog } from "../catalog/validate";
import { CURRENT_SCHEMA_VERSION, SETUP_FORMAT } from "./limits";
import { DEFAULT_ALERT_SETTINGS, type SetupV1 } from "./setupV1";

export interface NewSetupInput {
  /** UUID generated by the caller (no platform API inside `core`). */
  readonly id: string;
  readonly name: string;
  /** ISO 8601 timestamp. */
  readonly now: string;
  /** Desk catalog entry; defaults to the desk of the studio scene (`studio.json` desk.type). */
  readonly deskCatalogId?: string;
}

/** Empty setup: a default desk, no object. Returns null if the catalog has no such desk. */
export function createSetup(catalog: Catalog, input: NewSetupInput): SetupV1 | null {
  const desk = catalog.objectTypes.get(input.deskCatalogId ?? catalog.studio.desk.type);
  if (desk?.type !== DESK_TYPE) return null;
  return {
    format: SETUP_FORMAT,
    schemaVersion: CURRENT_SCHEMA_VERSION,
    id: input.id,
    name: input.name,
    createdAt: input.now,
    updatedAt: input.now,
    units: "mm",
    desk: {
      catalogId: desk.id,
      catalogVersion: desk.version,
      params: defaultParams(desk.params),
      materials: {},
    },
    objects: [],
    environment: { stylePreset: null, lighting: "neutral", room: null },
    alertSettings: { ...DEFAULT_ALERT_SETTINGS },
    extensions: {},
  };
}
